using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.AI;using UnityEditor;using FireSafety;using Newtonsoft.Json.Linq;
public static class AuditCampus {public static string Run(){var checks=new List<object>();void Check(string n,bool p,object e=null)=>checks.Add(new{name=n,pass=p,evidence=e});var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var replicas=all.Where(t=>t.name.EndsWith(" - environment only")).ToArray();Check("Five ground-floor classrooms",replicas.Length==4&&GameObject.Find("Classroom - licensed source art"));Check("Replicas have no FireSafety gameplay components",replicas.All(t=>t.GetComponentsInChildren<MonoBehaviour>(true).All(c=>c&&c.GetType().Namespace!="FireSafety")));Check("No missing scripts",all.Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject))==0);var bad=all.Select(t=>t.GetComponent<Renderer>()).Where(r=>r&&r.gameObject.activeInHierarchy&&r.sharedMaterials.Any(m=>!m||m.shader.name.Contains("InternalError"))).Select(r=>r.name).ToArray();Check("No missing or error-shader materials",bad.Length==0,bad);
var nav=UnityEngine.Object.FindAnyObjectByType<NavigationManager>();var routes=new List<object>();foreach(float z in new[]{0f,-17.1f,-8.55f,8.55f,17.1f}){var p=new Vector3(0,.05f,-1.95f+z);nav.Recalculate(p);var path=new NavMeshPath();NavMeshHit h;bool sampled=NavMesh.SamplePosition(p,out h,.4f,NavMesh.AllAreas);bool complete=sampled&&NavMesh.CalculatePath(h.position,nav.assembly.position,NavMesh.AllAreas,path)&&path.status==NavMeshPathStatus.PathComplete;routes.Add(new{z,complete,guidance=nav.Available});Check("Classroom z="+z+" connected to assembly",complete&&nav.Available);}
var crowd=UnityEngine.Object.FindAnyObjectByType<SchoolEvacuationController>();Check("One teacher and ten students",crowd.people.Length==11&&crowd.people.Count(p=>p.name=="Teacher")==1);Check("NPC animation references intact",crowd.people.All(p=>p.legacyAnimation[p.idleClip]!=null&&p.legacyAnimation[p.walkClip]!=null));
var upper=GameObject.Find("Campus exterior upgrade/Decorative upper storey - no access");Check("Decorative upper storey has no gameplay",upper&&upper.GetComponentsInChildren<MonoBehaviour>(true).All(c=>c.GetType().Namespace!="FireSafety"));var tris=NavMesh.CalculateTriangulation();Check("No walkable upper storey",tris.vertices.All(v=>v.y<3.25f));
var board=GameObject.Find("Campus exterior upgrade/SATHYABAMA UNIVERSITY name board");Check("Upper sign has exact university spelling",board.GetComponentsInChildren<TMPro.TMP_Text>().Any(t=>t.text=="SATHYABAMA UNIVERSITY"));Check("Old school name and assembly upright board hidden",all.Where(t=>t.name=="School exterior identity"||t.name=="Assembly sign"||t.name=="Assembly sign post").All(t=>!t.gameObject.activeInHierarchy));var evac=UnityEngine.Object.FindAnyObjectByType<EvacuationManager>();Check("Assembly trigger and destination preserved",evac.assemblyZone&&evac.assemblyZone.isTrigger&&Vector3.Distance(evac.assemblyZone.bounds.center,new Vector3(14.2f,1,-.2f))<.01f&&Vector3.Distance(nav.assembly.position,new Vector3(14.2f,0,-.2f))<.01f,new{center=evac.assemblyZone.bounds.center.ToString(),size=evac.assemblyZone.bounds.size.ToString()});Check("Two parked buses",GameObject.Find("Campus exterior upgrade/Campus school buses").transform.childCount==2);
var before=JArray.Parse(File.ReadAllText("../Documentation/CampusGameplayBefore.json"));var behaviours=all.SelectMany(t=>t.GetComponents<MonoBehaviour>()).Where(b=>b&&b.GetType().Namespace=="FireSafety").ToArray();var changes=new List<string>();foreach(var old in before){var b=behaviours.SingleOrDefault(x=>x.name==(string)old["name"]&&x.GetType().Name==(string)old["type"]);if(!b){changes.Add(old["name"]+" missing");continue;}var current=JObject.Parse(EditorJsonUtility.ToJson(b));var baseline=JObject.Parse((string)old["json"]);foreach(var prop in current.DescendantsAndSelf().OfType<JProperty>().Where(p=>p.Name=="instanceID").ToArray())prop.Value=0;foreach(var prop in baseline.DescendantsAndSelf().OfType<JProperty>().Where(p=>p.Name=="instanceID").ToArray())prop.Value=0;if(!JToken.DeepEquals(current,baseline))changes.Add(b.name+" / "+b.GetType().Name);}Check("Serialized gameplay settings match pre-upgrade snapshot",changes.Count==0,changes);
nav.ResetNavigation();var json=Newtonsoft.Json.JsonConvert.SerializeObject(new{checks,routes},Newtonsoft.Json.Formatting.Indented);File.WriteAllText("../Documentation/CampusSceneAudit.json",json);return json;}}


